function shouldPromptPhoneVerify(profile, smsLoginAvailable) {
	if (!profile || smsLoginAvailable !== true) return false;
	return typeof profile.email === "string" && profile.email.trim().length > 0 && profile.phoneVerified !== true;
}
/**
* Should the post-claim card offer to verify an email? Only for an account with
* no sign-in email (a phone-signed-in customer) that has not attached a verified
* one yet. No gating on login methods: email codes are always available.
*/
function shouldPromptEmailVerify(profile) {
	if (!profile) return false;
	const hasEmail = typeof profile.email === "string" && profile.email.trim().length > 0;
	const hasVerified = typeof profile.verifiedEmail === "string" && profile.verifiedEmail.trim().length > 0;
	return !hasEmail && !hasVerified;
}
