//#region ../deployed-source/src/lib/client/poa-conflict.ts
/**
* Maps the body of a 409 from POST /api/client/cases/[id]/poa to the copy the
* customer should see. The route sends one flag per block; "already signed" is
* only right for `alreadySigned`, so every other block gets its own message.
*/
function poaConflictKey(body) {
	const flags = body && typeof body === "object" ? body : {};
	if (flags.caseClosed === true) return "poa.error.caseClosed";
	if (flags.automationPaused === true) return "poa.error.onHold";
	if (flags.recoveryRequired === true) return "poa.error.recoveryRequired";
	if (flags.concurrent === true) return "poa.error.concurrent";
	if (flags.alreadySigned === true) return "poa.error.alreadySigned";
	return "poa.error.requestFailed";
}
