/**
* Where a case stands, as the index of the last stage reached. The case status is the source of
* truth for the later stages; before that, uploaded documents are what separates "opened" from
* "documents in".
*/
function caseStage({ status, documentCount }) {
	switch (status) {
		case "Paid":
		case "Closed": return 3;
		case "Submitted":
		case "AirlineResponded":
		case "Rejected":
		case "Escalated": return 2;
		default: return documentCount > 0 ? 1 : 0;
	}
}
