/**
* Marketing, login and saved new-claim links. `newClaim=auto` lets the dashboard decide: a customer with no
* claims lands straight on the claim form, one who already has claims lands on the dashboard. In-portal
* "new claim" buttons add `force=1` and always get the form (`newClaim=1`).
*/
async function NewClaimRedirect({ searchParams }) {
	const { force, ...params } = await searchParams;
	redirect(appendSearchParams("/client", {
		...params,
		newClaim: force === "1" ? "1" : "auto"
	}) + "#new-claim-form");
}
