//#region ../deployed-source/src/lib/website/calculator.ts
var DEFAULT_CALCULATOR = {
	type: "delay",
	distance: "medium",
	delayHours: "fourPlus",
	costs: "",
	costsCurrency: "EUR",
	notice: "late",
	alternative: false,
	denied: "overbooking",
	baggage: "lost",
	days: "short",
	returned: false,
	flight: ""
};
/** Existing public-site estimator, retained for parity. It is not a legal eligibility decision. */
function estimateWebsiteCompensation(c) {
	const n = WEBSITE_CALCULATOR.en;
	const base = n.distances.find((x) => x.id === c.distance)?.amount ?? 0;
	if (c.type === "delay") {
		if (c.delayHours === "under3") return { kind: "review" };
		const extra = !c.costsCurrency || c.costsCurrency === "EUR" ? Number(c.costs) : 0;
		return {
			kind: "amount",
			value: (c.distance === "long" && c.delayHours === "threeToFour" ? Math.round(base * .5) : base) + (Number.isFinite(extra) ? Math.max(0, extra) : 0)
		};
	}
	if (c.type === "cancellation") return c.notice === "early" ? { kind: "review" } : {
		kind: "amount",
		value: c.alternative ? Math.round(base * .5) : base
	};
	if (c.type === "denied") return c.denied === "voluntary" ? { kind: "review" } : {
		kind: "amount",
		value: base
	};
	const min = n.baggageAmountMin, max = n.baggageAmount;
	return {
		kind: "amount",
		value: c.baggage === "damaged" ? Math.round((min + max) / 2) : c.returned ? min : Math.round(min + (max - min) * (c.days === "short" ? .3 : c.days === "medium" ? .65 : 1))
	};
}
